local BackgammonMaker = {}
local PRODUCTS = {
    simple_wood_backgammon = { name = "Preprost leseni tavla", woodCost = 3, paintCost = 1, time = 5, cost = 90, happiness = 3, prestige = 2, description = "Preprost leseni tavla za krčme." },
    inlaid_walnut_backgammon = { name = "Vložkana orehov tavla", woodCost = 3, leatherCost = 1, paintCost = 1, time = 8, cost = 240, happiness = 4, prestige = 5, description = "Vložkana orehov tavla za trgovce." },
    silver_trimmed_backgammon = { name = "Srebrnoobrobljeni tavla", woodCost = 3, silverCost = 1, leatherCost = 1, paintCost = 1, time = 11, cost = 580, happiness = 5, prestige = 10, description = "Srebrnoobrobljeni tavla za plemiče." },
    gold_inlaid_backgammon = { name = "Zlatovloženi tavla", woodCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, paintCost = 1, time = 15, cost = 1300, happiness = 6, prestige = 18, description = "Zlatovloženi tavla za visoke plemiče." },
    jewel_set_backgammon = { name = "Draguljasta tavla", woodCost = 3, goldCost = 2, silverCost = 1, leatherCost = 1, paintCost = 1, jewelCost = 1, time = 19, cost = 2900, happiness = 8, prestige = 30, description = "Tavla z draguljem za visoko plemstvo." },
    royal_grand_backgammon = { name = "Kraljevski veliki tavla", woodCost = 5, goldCost = 3, silverCost = 2, leatherCost = 1, paintCost = 1, jewelCost = 2, pearlCost = 2, time = 26, cost = 6200, happiness = 14, prestige = 60, description = "Veliki kraljevski tavla z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    backgammon_workshop = { name = "Tavlarska delavnica", cost = { gold = 240, wood = 140, stone = 100, paint = 6 }, upkeep = 5, qualityBonus = 5 },
    gaming_loft = { name = "Igralna podstrešje", cost = { gold = 880, wood = 280, stone = 220, silver = 6, leather = 6 }, upkeep = 20, qualityBonus = 18 },
    master_backgammon_atelier = { name = "Mojstrski tavlarski atelje", cost = { gold = 2500, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_gaming_palace = { name = "Kraljevska igralska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
BackgammonMaker.woodStock = 18; BackgammonMaker.leatherStock = 10; BackgammonMaker.paintStock = 12; BackgammonMaker.silverStock = 6; BackgammonMaker.goldStock = 6; BackgammonMaker.jewelStock = 4; BackgammonMaker.pearlStock = 4
BackgammonMaker.productStock = {}; BackgammonMaker.buildings = {}; BackgammonMaker.maker = nil; BackgammonMaker.activeMaking = {}; BackgammonMaker.totalProducts = 0; BackgammonMaker.dayTimer = 0
function BackgammonMaker.init() BackgammonMaker.woodStock=18; BackgammonMaker.leatherStock=10; BackgammonMaker.paintStock=12; BackgammonMaker.silverStock=6; BackgammonMaker.goldStock=6; BackgammonMaker.jewelStock=4; BackgammonMaker.pearlStock=4; BackgammonMaker.productStock={}; BackgammonMaker.buildings={}; BackgammonMaker.maker=nil; BackgammonMaker.activeMaking={}; BackgammonMaker.totalProducts=0; BackgammonMaker.dayTimer=0; print("[BackgammonMaker] Royal Backgammon Maker System initialized (6 products, 4 buildings)") end
function BackgammonMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BackgammonMaker.maker={name=n or ("Tavlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tavlar najet: %s (spretnost: %d)",BackgammonMaker.maker.name,s),"success") end; return true end
function BackgammonMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BackgammonMaker.build(id) local ok,e=BackgammonMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BackgammonMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BackgammonMaker.getQualityBonus() local b=0; for _,bd in ipairs(BackgammonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BackgammonMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BackgammonMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BackgammonMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.paintCost and BackgammonMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and BackgammonMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BackgammonMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BackgammonMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BackgammonMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BackgammonMaker.buildings==0 then return false,"Potrebna tavlarska delavnica" end; if not BackgammonMaker.maker then return false,"Potreben tavlar" end; return true end
function BackgammonMaker.make(pt,qty) qty=qty or 1; local ok,e=BackgammonMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BackgammonMaker.woodStock=BackgammonMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BackgammonMaker.leatherStock=BackgammonMaker.leatherStock-d.leatherCost*qty end; if d.paintCost then BackgammonMaker.paintStock=BackgammonMaker.paintStock-d.paintCost*qty end; if d.silverCost then BackgammonMaker.silverStock=BackgammonMaker.silverStock-d.silverCost*qty end; if d.goldCost then BackgammonMaker.goldStock=BackgammonMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BackgammonMaker.jewelStock=BackgammonMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BackgammonMaker.pearlStock=BackgammonMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BackgammonMaker.maker then t=math.max(1,t-math.floor(BackgammonMaker.maker.skill/13)) end; table.insert(BackgammonMaker.activeMaking,{id="backgammon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BackgammonMaker.completeMaking(m) local q=1.0+(BackgammonMaker.getQualityBonus()/100); if BackgammonMaker.maker then q=q+(BackgammonMaker.maker.skill/140) end; q=math.min(2.5,q); BackgammonMaker.productStock[m.productType]=(BackgammonMaker.productStock[m.productType] or 0)+m.quantity; BackgammonMaker.totalProducts=BackgammonMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BackgammonMaker.maker then BackgammonMaker.maker.itemsMade=BackgammonMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BackgammonMaker.maker.skill=math.min(100,BackgammonMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tavla izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"backgammon.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BackgammonMaker.update(dt) if not _G.state then return end; BackgammonMaker.dayTimer=BackgammonMaker.dayTimer+dt; if BackgammonMaker.dayTimer>=30 then BackgammonMaker.dayTimer=0; for i=#BackgammonMaker.activeMaking,1,-1 do local m=BackgammonMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BackgammonMaker.completeMaking(m); table.remove(BackgammonMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BackgammonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BackgammonMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BackgammonMaker.getStats() return {woodStock=BackgammonMaker.woodStock,leatherStock=BackgammonMaker.leatherStock,paintStock=BackgammonMaker.paintStock,silverStock=BackgammonMaker.silverStock,goldStock=BackgammonMaker.goldStock,jewelStock=BackgammonMaker.jewelStock,pearlStock=BackgammonMaker.pearlStock,productStock=BackgammonMaker.productStock,numBuildings=#BackgammonMaker.buildings,hasMaker=BackgammonMaker.maker~=nil,makerName=BackgammonMaker.maker and BackgammonMaker.maker.name or "—",makerSkill=BackgammonMaker.maker and BackgammonMaker.maker.skill or 0,activeMaking=#BackgammonMaker.activeMaking,totalProducts=BackgammonMaker.totalProducts} end
return BackgammonMaker
